package com.rustypayments.modern;

import com.rustypayments.PaymentCalendar;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.Month;
import java.time.MonthDay;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.temporal.ChronoUnit;
import java.util.Set;

public class ModernPaymentCalendar implements PaymentCalendar {

    private static final ZoneId BANK_ZONE = ZoneId.of("Europe/Warsaw");
    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    private static final DateTimeFormatter INSTANT_FORMAT = DateTimeFormatter.ISO_OFFSET_DATE_TIME;
    private static final LocalTime CUT_OFF_TIME = LocalTime.of(16, 0);

    private static final Set<MonthDay> HOLIDAYS = Set.of(
        MonthDay.of(Month.JANUARY, 1),
        MonthDay.of(Month.JANUARY, 6),
        MonthDay.of(Month.MAY, 1),
        MonthDay.of(Month.MAY, 3),
        MonthDay.of(Month.AUGUST, 15),
        MonthDay.of(Month.NOVEMBER, 1),
        MonthDay.of(Month.NOVEMBER, 11),
        MonthDay.of(Month.DECEMBER, 25),
        MonthDay.of(Month.DECEMBER, 26)
    );

    @Override
    public boolean isBusinessDay(String date) {
        LocalDate d = parseLocalDate(date);
        return checkIsBusinessDay(d);
    }

    @Override
    public String processingDate(String submittedAt) {
        ZonedDateTime zdt = parseZonedDateTime(submittedAt).withZoneSameInstant(BANK_ZONE);
        LocalDate localDate = zdt.toLocalDate();
        LocalTime localTime = zdt.toLocalTime();

        if (checkIsBusinessDay(localDate) && !localTime.isAfter(CUT_OFF_TIME)) {
            return localDate.toString();
        } else {
            return nextBusinessDay(localDate).toString();
        }
    }

    @Override
    public String settlementDate(String submittedAt) {
        ZonedDateTime zdt = parseZonedDateTime(submittedAt).withZoneSameInstant(BANK_ZONE);
        LocalDate pDate = processingDate(submittedAt.substring(0, submittedAt.lastIndexOf('T') + 1) + "00:00:00+01:00");
        // Wait, the above is a hack. Let's calculate processing date correctly.
        // The processingDate is a string. We need to re-parse it to get the LocalDate.
        LocalDate processed = LocalDate.parse(processingDate(submittedAt), DATE_FORMAT);
        return nextBusinessDay(processed.plusDays(1)).toString();
    }

    // Redefining settlementDate to be safer and more direct
    @Override
    public String settlementDate(String submittedAt) {
        // We need the processing date of the same instant.
        // To avoid double parsing and ambiguity, we calculate it internally.
        ZonedDateTime zdt = parseZonedDateTime(submittedAt).withZoneSameInstant(BANK_ZONE);
        LocalDate localDate = zdt.toLocalDate();
        LocalDate processed;
        if (checkIsBusinessDay(localDate) && !zdt.toLocalTime().isAfter(CUT_OFF_TIME)) {
            processed = localDate;
        } else {
            processed = nextBusinessDay(localDate);
        }
        // Settlement is first business day strictly after processing date.
        return nextBusinessDay(processed.plusDays(1)).toString();
    }

    @Override
    public int daysLate(String dueDate, String paidAt) {
        LocalDate due = parseLocalDate(dueDate);
        ZonedDateTime paid = parseZonedDateTime(paidAt).withZoneSameInstant(BANK_ZONE);
        long diff = ChronoUnit.DAYS.between(due, paid.toLocalDate());
        return (int) Math.max(0, diff);
    }

    @Override
    public String addMonths(String date, int months) {
        LocalDate d = parseLocalDate(date);
        boolean isLastDay = d.getDayOfMonth() == d.lengthOfMonth();
        LocalDate result = d.plusMonths(months);
        if (isLastDay) {
            result = result.withDayOfMonth(result.lengthOfMonth());
        }
        return result.toString();
    }

    private boolean checkIsBusinessDay(LocalDate d) {
        int dayOfWeek = d.getDayOfWeek().getValue();
        if (dayOfWeek == 6 || dayOfWeek == 7) {
            return false;
        }
        return !HOLIDAYS.contains(MonthDay.from(d));
    }

    private LocalDate nextBusinessDay(LocalDate from) {
        LocalDate current = from;
        while (!checkIsBusinessDay(current)) {
            current = current.plusDays(1);
        }
        return current;
    }

    private LocalDate parseLocalDate(String text) {
        if (text == null) throw new IllegalArgumentException();
        try {
            return LocalDate.parse(text, DATE_FORMAT);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException(e);
        }
    }

    private ZonedDateTime parseZonedDateTime(String text) {
        if (text == null) throw new IllegalArgumentException();
        try {
            return ZonedDateTime.parse(text, INSTANT_FORMAT);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException(e);
        }
    }
}

